1	import dagre from "dagre";
2	import type {
3		EntityType,
4		RelationshipType,
5		RelationshipTypeRule,
6	} from "@/lib/api";
7	import { isSystemEntityType } from "@/lib/reserved";
8	
9	/**
10	 * Pure model + layout for the entity-type ERD.
11	 *
12	 * Boxes are entity TYPES (not rows); edges are the DECLARED
13	 * `entity_relationship_type_rules` (source→target slug pairs), so the diagram
14	 * renders correctly even for an org with zero entity rows. Kept free of React
15	 * and of the data-fetching layer so the shape logic is unit-testable and the
16	 * rules source can change (per-slug fan-out today, a bulk endpoint later)
17	 * without touching the view.
18	 */
19	
20	/** A field row rendered inside a type's box. */
21	export interface SchemaNodeField {
22		name: string;
23		/** JSON-schema type, when the property declares one. */
24		type?: string;
25	}
26	
27	export interface SchemaNodeData {
28		slug: string;
29		label: string;
30		/** Owner slug, so a node can link straight to its entity-type editor. */
31		ownerSlug: string;
32		icon?: string | null;
33		fields: SchemaNodeField[];
34		/** Reserved `$…` type, rendered in a distinct color rather than hidden. */
35		isSystem: boolean;
36		entityCount?: number;
37		/** Edge-specific handles keep parallel relationships from overlapping. */
38		sourceHandleIds: string[];
39		targetHandleIds: string[];
40		/** Self-loop targets attach above the node so their paths remain visible. */
41		selfTargetHandleIds: string[];
42	}
43	
44	interface SchemaEdgeData {
45		/** Relationship type slug (`works_at`), not the rule id. */
46		slug: string;
47		label: string;
48		/** Symmetric relations render without an arrowhead — the pair is unordered. */
49		isSymmetric: boolean;
50	}
51	
52	interface SchemaGraphNode {
53		id: string;
54		data: SchemaNodeData;
55		position: { x: number; y: number };
56		width: number;
57		height: number;
58	}
59	
60	export interface SchemaGraphEdge {
61		id: string;
62		source: string;
63		target: string;
64		data: SchemaEdgeData;
65	}
66	
67	interface SchemaGraph {
68		nodes: SchemaGraphNode[];
69		edges: SchemaGraphEdge[];
70	}
71	
72	/** Rules keyed by the relationship-type slug they belong to. */
73	export type RulesBySlug = Record<string, RelationshipTypeRule[]>;
74	
75	/**
76	 * Which edges should carry a visible label.
77	 *
78	 * Parallel edges between the same pair stack identical text in the same spot,
79	 * so only the first of a pair is labelled. Keyed by the PAIR rather than by
80	 * relationship type: one type can join several different pairs (`contains`
81	 * covers order→product and invoice→payment), and keying by type alone would
82	 * caption an unrelated pair with the first pair's name.
83	 */
84	export function labelledEdgeIds(edges: SchemaGraphEdge[]): Set<string> {
85		const seenPairs = new Set<string>();
86		const labelled = new Set<string>();
87		for (const edge of edges) {
88			const pairKey = `${edge.data.slug}|${edge.source}|${edge.target}`;
89			if (seenPairs.has(pairKey)) continue;
90			seenPairs.add(pairKey);
91			labelled.add(edge.id);
92		}
93		return labelled;
94	}
95	
96	const NODE_WIDTH = 220;
97	const HEADER_HEIGHT = 44;
98	
99	function compareSlugs(a: { slug: string }, b: { slug: string }): number {
100		return a.slug < b.slug ? -1 : a.slug > b.slug ? 1 : 0;
101	}
102	
103	/**
104	 * Keep active relationship types only. The accessible list is tenant-first and
105	 * may also contain a public type with the same slug; `list_rules` resolves that
106	 * slug tenant-first, so keep the first type to label its rules consistently.
107	 */
108	export function selectRelationshipTypesForGraph(
109		relationshipTypes: RelationshipType[],
110	): RelationshipType[] {
111		const seen = new Set<string>();
112		return relationshipTypes.filter((relationshipType) => {
113			if (relationshipType.status !== "active") return false;
114			if (seen.has(relationshipType.slug)) return false;
115			seen.add(relationshipType.slug);
116			return true;
117		});
118	}
119	
120	/**
121	 * Field rows for a type's box, read from its `metadata_schema` JSON-schema
122	 * `properties`. `$resource` is a deliberate graph anchor with an empty schema,
123	 * so an empty list is expected rather than a failure.
124	 */
125	export function schemaFields(entityType: EntityType): SchemaNodeField[] {
126		const schema = entityType.metadata_schema;
127		if (!schema || typeof schema !== "object") return [];
128		const properties = (schema as Record<string, unknown>).properties;
129		if (!properties || typeof properties !== "object") return [];
130	
131		return Object.entries(properties as Record<string, unknown>).map(
132			([name, spec]) => {
133				const type =
134					spec && typeof spec === "object"
135						? (spec as Record<string, unknown>).type
136						: undefined;
137				return { name, type: typeof type === "string" ? type : undefined };
138			},
139		);
140	}
141	
142	/**
143	 * Build the unpositioned graph. Only rules whose BOTH endpoints resolve to a
144	 * known type become edges — a rule naming a deleted type would otherwise
145	 * produce an edge to a node that does not exist.
146	 */
147	export function buildSchemaGraph(opts: {
148		entityTypes: EntityType[];
149		relationshipTypes: RelationshipType[];
150		rulesBySlug: RulesBySlug;
151		ownerSlug: string;
152	}): { nodes: Omit<SchemaGraphNode, "position">[]; edges: SchemaGraphEdge[] } {
153		const { entityTypes, relationshipTypes, rulesBySlug, ownerSlug } = opts;
154		const orderedEntityTypes = [...entityTypes].sort(compareSlugs);
155		const resolvedRelationshipTypes =
156			selectRelationshipTypesForGraph(relationshipTypes).sort(compareSlugs);
157	
158		const knownSlugs = new Set(orderedEntityTypes.map((et) => et.slug));
159		const edges: SchemaGraphEdge[] = [];
160		const sourceHandles = new Map<string, string[]>();
161		const targetHandles = new Map<string, string[]>();
162		const selfTargetHandles = new Map<string, string[]>();
163	
164		for (const rt of resolvedRelationshipTypes) {
165			const rules = [...(rulesBySlug[rt.slug] ?? [])].sort((a, b) => a.id - b.id);
166	
167			for (const rule of rules) {
168				const source = rule.source_entity_type_slug;
169				const target = rule.target_entity_type_slug;
170				if (!knownSlugs.has(source) || !knownSlugs.has(target)) continue;
171	
172				const edge = {
173					// Rule id keeps sibling rules of one relationship type distinct.
174					id: `rule-${rule.id}`,
175					source,
176					target,
177					data: {
178						slug: rt.slug,
179						label: rt.name || rt.slug,
180						isSymmetric: rt.is_symmetric,
181					},
182				};
183				edges.push(edge);
184				sourceHandles.set(source, [
185					...(sourceHandles.get(source) ?? []),
186					`${edge.id}-source`,
187				]);
188				const targetHandleMap =
189					source === target ? selfTargetHandles : targetHandles;
190				targetHandleMap.set(target, [
191					...(targetHandleMap.get(target) ?? []),
192					`${edge.id}-target`,
193				]);
194			}
195		}
196	
197		const nodes = orderedEntityTypes.map((et) => {
198			const fields = schemaFields(et);
199			return {
200				id: et.slug,
201				width: NODE_WIDTH,
202				// Header-only: the diagram is about relationships, and field lists
203				// compete with the edges for attention past a handful of types.
204				height: HEADER_HEIGHT,
205				data: {
206					slug: et.slug,
207					label: et.name || et.slug,
208					ownerSlug,
209					icon: et.icon,
210					fields,
211					isSystem: isSystemEntityType(et),
212					entityCount: et.entity_count,
213					sourceHandleIds: sourceHandles.get(et.slug) ?? [],
214					targetHandleIds: targetHandles.get(et.slug) ?? [],
215					selfTargetHandleIds: selfTargetHandles.get(et.slug) ?? [],
216				},
217			};
218		});
219	
220		return { nodes, edges };
221	}
222	
223	const MARGIN = 24;
224	/** Gap between the connected flow and the unconnected band beneath it. */
225	const BAND_GAP = 72;
226	
227	/**
228	 * Deterministic dagre layout — same input always yields the same arrangement,
229	 * so positions never need persisting and a reload does not reshuffle the map.
230	 *
231	 * Only types that a rule actually touches go through dagre. Unconnected types
232	 * have no edge to rank them, so dagre packs them into the first column, which
233	 * stretches the connected flow vertically and reads as if they belonged to it.
234	 * They get their own row beneath the diagram instead.
235	 */
236	function layoutSchemaGraph(graph: {
237		nodes: Omit<SchemaGraphNode, "position">[];
238		edges: SchemaGraphEdge[];
239	}): SchemaGraph {
240		const connected = new Set<string>();
241		for (const edge of graph.edges) {
242			connected.add(edge.source);
243			connected.add(edge.target);
244		}
245		const flowNodes = graph.nodes.filter((node) => connected.has(node.id));
246		const bandNodes = graph.nodes.filter((node) => !connected.has(node.id));
247	
248		const g = new dagre.graphlib.Graph();
249		g.setGraph({
250			rankdir: "LR",
251			ranksep: 120,
252			nodesep: 32,
253			marginx: MARGIN,
254			marginy: MARGIN,
255		});
256		g.setDefaultEdgeLabel(() => ({}));
257	
258		for (const node of flowNodes) {
259			g.setNode(node.id, { width: node.width, height: node.height });
260		}
261		for (const edge of graph.edges) {
262			// Self-references do not separate ranks, so they do not participate in
263			// node layout. React Flow still receives and renders the edge.
264			if (edge.source === edge.target) continue;
265			g.setEdge(edge.source, edge.target);
266		}
267	
268		dagre.layout(g);
269	
270		const positioned = flowNodes.map((node) => {
271			const laidOut = g.node(node.id);
272			// dagre reports centers; React Flow positions from the top-left corner.
273			return {
274				...node,
275				position: {
276					x: (laidOut?.x ?? 0) - node.width / 2,
277					y: (laidOut?.y ?? 0) - node.height / 2,
278				},
279			};
280		});
281	
282		// Lay the unconnected band out left-to-right under the deepest flow node.
283		const flowBottom = positioned.reduce(
284			(max, node) => Math.max(max, node.position.y + node.height),
285			MARGIN,
286		);
287		const bandTop = positioned.length > 0 ? flowBottom + BAND_GAP : MARGIN;
288		let bandX = MARGIN;
289		const banded = bandNodes.map((node) => {
290			const position = { x: bandX, y: bandTop };
291			bandX += node.width + 32;
292			return { ...node, position };
293		});
294	
295		// Preserve the caller's node order so the output does not depend on which
296		// types happen to be connected.
297		const byId = new Map(
298			[...positioned, ...banded].map((node) => [node.id, node]),
299		);
300		const nodes = graph.nodes.map((node) => byId.get(node.id) ?? {
301			...node,
302			position: { x: MARGIN, y: MARGIN },
303		});
304	
305		return { nodes, edges: graph.edges };
306	}
307	
308	/** Build + lay out in one step. */
309	export function buildLaidOutSchemaGraph(opts: {
310		entityTypes: EntityType[];
311		relationshipTypes: RelationshipType[];
312		ownerSlug: string;
313		rulesBySlug: RulesBySlug;
314	}): SchemaGraph {
315		return layoutSchemaGraph(buildSchemaGraph(opts));
316	}
