1	import { type UseQueryResult, useQueries } from "@tanstack/react-query";
2	import { useCallback, useMemo } from "react";
3	import { useOrgContext } from "@/hooks/use-org-context";
4	import {
5		type RelationshipTypeRule,
6		useEntityTypes,
7		useRelationshipTypeRules,
8		useRelationshipTypes,
9	} from "@/lib/api/entities";
10	import {
11		buildLaidOutSchemaGraph,
12		type RulesBySlug,
13		selectRelationshipTypesForGraph,
14	} from "./entity-schema-graph";
15	
16	/**
17	 * Data for the entity-type ERD.
18	 *
19	 * Unlike `useVisibleEntityTypes` (rail + scope bar) this KEEPS system types —
20	 * `$resource` is the ACL anchor for Slack channels and GitHub repos, so it is
21	 * one of the more informative nodes on the map. They are flagged, not dropped,
22	 * and the view colors them differently.
23	 *
24	 * Rules are fetched per relationship type (`list_rules` takes one slug), so this
25	 * is 1+N requests where N is the unique relationship-type count. A bulk rules
26	 * action can replace only this hook later;
27	 * `buildLaidOutSchemaGraph` is pure and does not care where rules came from.
28	 */
29	export function useEntitySchemaGraph(ownerSlug: string) {
30		const { orgContext, hasOrgContext } = useOrgContext();
31		const {
32			data: entityTypes = [],
33			isLoading: isTypesLoading,
34			isError: isTypesError,
35		} = useEntityTypes(orgContext);
36		const {
37			data: relationshipTypes = [],
38			isLoading: isRelTypesLoading,
39			isError: isRelTypesError,
40		} = useRelationshipTypes(orgContext);
41	
42		const scopedTypes = useMemo(
43			() =>
44				entityTypes.filter(
45					(et) => !et.organization_slug || et.organization_slug === ownerSlug,
46				),
47			[entityTypes, ownerSlug],
48		);
49	
50		const resolvedRelationshipTypes = useMemo(
51			() => selectRelationshipTypesForGraph(relationshipTypes),
52			[relationshipTypes],
53		);
54	
55		const combineRuleQueries = useCallback(
56			(results: UseQueryResult<RelationshipTypeRule[]>[]) => {
57				const bySlug: RulesBySlug = {};
58				resolvedRelationshipTypes.forEach((rt, idx) => {
59					const rules = results[idx]?.data;
60					if (rules?.length) bySlug[rt.slug] = rules;
61				});
62				return {
63					rulesBySlug: bySlug,
64					isRulesLoading: results.some((result) => result.isLoading),
65					isRulesError: results.some((result) => result.isError),
66				};
67			},
68			[resolvedRelationshipTypes],
69		);
70	
71		// One `list_rules` per relationship type, run in parallel. `useQueries` takes
72		// a dynamic-length list, so the query count can track the type count without
73		// violating the rules of hooks.
74		//
75		// `.queryOptions()` does not carry the hook's `enabled` predicate, so gate
76		// explicitly when there is no org context.
77		const { rulesBySlug, isRulesLoading, isRulesError } = useQueries({
78			queries: resolvedRelationshipTypes.map((rt) => ({
79				...useRelationshipTypeRules.queryOptions(rt.slug, orgContext),
80				enabled: hasOrgContext,
81			})),
82			// Fold the per-slug results in `combine` so the returned map is memoized on
