describe("collapsing parallel rules", () => {
	it("folds repeated rules on one pair into a single counted edge", () => {
		// Three identical person→company rules drew three overlapping paths with
		// identical labels: three crossings, no extra information.
		const { edges } = buildSchemaGraph({
			entityTypes: [entityType("person"), entityType("company")],
			relationshipTypes: [relType("works_at")],
			rulesBySlug: {
				works_at: [
					rule("person", "company"),
					rule("person", "company"),
					rule("person", "company"),
				],
			},
			ownerSlug: "acme",
		});

		expect(edges).toHaveLength(1);
		expect(edges[0].data.ruleCount).toBe(3);
		expect(edges[0].data.ruleIds).toHaveLength(3);
	});

	it("keeps distinct relationship types on one pair as separate edges", () => {
		// `works_at` and `founded` are different claims about person→company;
		// collapsing them would assert one relationship where there are two.
		const { edges } = buildSchemaGraph({
			entityTypes: [entityType("person"), entityType("company")],
			relationshipTypes: [relType("works_at"), relType("founded")],
			rulesBySlug: {
				works_at: [rule("person", "company")],
				founded: [rule("person", "company")],
			},
			ownerSlug: "acme",
		});

		expect(edges).toHaveLength(2);
		expect(edges.every((edge) => edge.data.ruleCount === 1)).toBe(true);
	});

	it("keeps the two directions of one type as separate edges", () => {
		// person→company and company→person are opposite claims, so an unordered
		// pair key would wrongly fold them together.
		const { edges } = buildSchemaGraph({
			entityTypes: [entityType("person"), entityType("company")],
			relationshipTypes: [relType("refers")],
			rulesBySlug: {
				refers: [rule("person", "company"), rule("company", "person")],
			},
			ownerSlug: "acme",
		});

		expect(edges).toHaveLength(2);
	});

	it("gives a collapsed edge exactly one handle per endpoint", () => {
		// Handles are spread across a 44px box; leaving three handles for one
		// drawn path put them ~5px apart and reintroduced the hairball.
		const { nodes, edges } = buildSchemaGraph({
			entityTypes: [entityType("person"), entityType("company")],
			relationshipTypes: [relType("works_at")],
			rulesBySlug: {
				works_at: [rule("person", "company"), rule("person", "company")],
			},
			ownerSlug: "acme",
		});
		const person = nodes.find((n) => n.id === "person");
		const company = nodes.find((n) => n.id === "company");

		expect(person?.data.sourceHandleIds).toEqual([`${edges[0].id}-source`]);
		expect(company?.data.targetHandleIds).toEqual([`${edges[0].id}-target`]);
	});
});

describe("schemaClusters", () => {
	function clustersFor(pairs: [string, string, string][], extra: string[] = []) {
		const types = [
			...new Set([...pairs.flatMap(([, s, t]) => [s, t]), ...extra]),
		];
		const rulesBySlug: Record<string, ReturnType<typeof rule>[]> = {};
		for (const [slug, source, target] of pairs) {
			rulesBySlug[slug] ??= [];
			rulesBySlug[slug].push(rule(source, target));
		}
		const graph = buildSchemaGraph({
			entityTypes: types.map((slug) => entityType(slug)),
			relationshipTypes: [...new Set(pairs.map(([slug]) => slug))].map((slug) =>
				relType(slug),
			),
			rulesBySlug,
			ownerSlug: "acme",
		});
		return schemaClusters(graph);
	}

	it("groups types joined transitively into one cluster", () => {
		// person→company and company→deal share `company`, so all three are one
		// component even though person and deal are not directly linked.
		const clusters = clustersFor([
			["works_at", "person", "company"],
			["owns", "company", "deal"],
		]);

		expect(clusters).toHaveLength(1);
		expect(clusters[0].slugs).toEqual(["company", "deal", "person"]);
	});

	it("separates components that share no relationship", () => {
		const clusters = clustersFor([
			["works_at", "person", "company"],
			["contains", "order", "product"],
		]);

		expect(clusters).toHaveLength(2);
		expect(clusters.map((c) => c.slugs)).toEqual([
			["company", "person"],
			["order", "product"],
		]);
	});

	it("excludes types no rule touches", () => {
		// Nine single-node "clusters" would bury the one grouping that means
		// something; islands are listed separately by the view.
		const clusters = clustersFor(
			[["works_at", "person", "company"]],
			["goal", "note"],
		);

		expect(clusters).toHaveLength(1);
		expect(clusters[0].slugs).toEqual(["company", "person"]);
	});

	it("counts a self-referencing type as its own cluster", () => {
		// It has a relationship to show, so it is not an island.
		const clusters = clustersFor([["reports_to", "person", "person"]]);

		expect(clusters).toHaveLength(1);
		expect(clusters[0].slugs).toEqual(["person"]);
		expect(clusters[0].edgeIds).toHaveLength(1);
	});

	it("orders clusters biggest first", () => {
		const clusters = clustersFor([
			["contains", "order", "product"],
			["works_at", "person", "company"],
			["owns", "company", "deal"],
		]);

		expect(clusters[0].slugs).toHaveLength(3);
		expect(clusters[1].slugs).toHaveLength(2);
	});

	it("carries only the edges internal to each cluster", () => {
		const clusters = clustersFor([
			["works_at", "person", "company"],
			["contains", "order", "product"],
		]);
		const allEdgeIds = clusters.flatMap((c) => c.edgeIds);

		expect(clusters.every((c) => c.edgeIds.length === 1)).toBe(true);
		expect(new Set(allEdgeIds).size).toBe(2);
	});
});

