function resolvedPathQueryOptions(
	path: string,
	orgContext?:
		| { organizationId?: string | null; slug?: string | null }
		| string
		| null,
	options?: { includeBootstrap?: boolean },
) {
	const ctx = normalizeOrgContext(orgContext);
	const orgSelector =
		ctx.organizationId || ctx.slug ? resolveOrgSelector(ctx) : undefined;
	const normalizedPath = normalizeResolvedPathInput(path);
	// Key on slug-OR-orgId (whichever's set) but not both — slug uniquely
	// identifies the org, and orgId may arrive asynchronously after first
	// mount once `/api/organizations` resolves. Keying on both meant the
	// initial render fired one request with `organizationId=undefined` and
	// refetched moments later when orgId materialised.
	return {
		queryKey: [
			"resolve-path",
			normalizedPath,
			ctx.slug || ctx.organizationId,
			options?.includeBootstrap ?? false,
		] as const,
		queryFn: async () => {
			const result = await apiCall<ResolvePathResult>(
				"resolve_path",
				{
					path: normalizedPath,
					include_bootstrap: options?.includeBootstrap ?? false,
				},
				orgSelector,
			);
			return result;
		},
		staleTime: 300000,
		normalizedPath,
	};
}

export function useResolvedPath(
	path: string,
	orgContext?:
		| { organizationId?: string | null; slug?: string | null }
		| string
		| null,
	options?: { includeBootstrap?: boolean },
) {
	const { normalizedPath, ...opts } = resolvedPathQueryOptions(
		path,
		orgContext,
		options,
	);
	return useQuery({
		...opts,
		enabled: !!normalizedPath,
		placeholderData: getResolvedPathInitialData(normalizedPath),
	});
}

export async function apiCall<T>(
  endpoint: string,
  body: Record<string, unknown>,
  orgContext?: string | ApiOrgContext,
  options?: { timeoutMs?: number }
): Promise<T> {
  const scope = resolveApiScope(orgContext);
  const response = await fetchWithTimeout(`${API_URL}/api/${scope.slug}/${endpoint}`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    credentials: 'include',
    body: JSON.stringify(body),
    timeoutMs: options?.timeoutMs,
  });

  if (!response.ok) {
    const rawBody = await response.text();
    let message = `API error: ${response.status}`;

    if (rawBody) {
      try {
        const parsed = JSON.parse(rawBody) as { error?: string; message?: string };
        message = parsed.message || parsed.error || message;
      } catch {
        message = rawBody;
      }
    }

    throw new Error(message);
  }

  return response.json();
}

