/**
 * An API failure that remembers which HTTP status produced it.
 *
 * Callers used to get a bare `Error`, so every failure looked alike: TanStack
 * set `isError` for a 404 and a 500 identically, and a page keying its empty
 * state on that flag told people their organization did not exist whenever the
 * server was merely down. Anything that must distinguish "not there" from
 * "broken" needs the status, so it travels with the error.
 */
export class ApiError extends Error {
  readonly status: number;

  constructor(message: string, status: number) {
    super(message);
    this.name = 'ApiError';
    this.status = status;
  }
}

/**
 * True when a request failed because the thing is not there (404), as opposed
 * to any other failure. Narrow on purpose: 403 is "exists, not yours", which is
 * a different message again.
 */
export function isNotFoundError(error: unknown): boolean {
  return error instanceof ApiError && error.status === 404;
}

