/**
 * True when a request failed because the thing is not there (404). Narrow on
 * purpose: 403 is "exists, not yours", which warrants a different message.
 */
export function isNotFoundError(error: unknown): boolean {
  return error instanceof ApiError && error.status === 404;
}

/**
 * True when the SERVER failed, rather than the request being answered with a
 * refusal. Only 5xx and transport-level failures qualify.
 *
 * The distinction matters for empty states: a 401/403 means "log in" or "ask
 * for access" and has its own path through the UI, so lumping every non-404
 * into "something went wrong on our end" strands people on an error page
 * instead of sending them to sign in.
 */
export function isServerError(error: unknown): boolean {
  if (error instanceof ApiError) return error.status >= 500;
  // A transport failure (offline, DNS, timeout) never reached a server to get
  // a status, and is an outage from the user's point of view.
  return error instanceof Error;
}

