export function isServerError(error: unknown): boolean {
  if (error instanceof ApiError) return error.status >= 500;
  // A transport failure (offline, DNS, timeout) never reached a server to get
  // a status, and is an outage from the user's point of view.
  return error instanceof Error;
}

input.new_string:
export function isServerError(error: unknown): boolean {
  if (error instanceof ApiError) return error.status >= 500;
  if (!(error instanceof Error)) return false;
  // Not an `ApiError`, so the status did not survive. Recover it from the
  // `API error: <status>` message the older raw throws produced rather than
  // assuming a transport failure: reading a 401 as an outage is exactly the
  // bug this function exists to prevent, and it would come back silently the
  // next time a call site throws a plain `Error`.
  const status = /^API error: (\d{3})$/.exec(error.message)?.[1];
  if (status) return Number(status) >= 500;
  // No status anywhere: a genuine transport failure (offline, DNS, timeout)
  // never reached a server, which is an outage from the user's point of view.
  return true;
}

