		).toBeTruthy();
	});

	it("hides schema authoring from non-admin members", () => {
		// `create` and `add_rule` are OWNER_ADMIN_ACTIONS server-side, so showing
		// these to a member only buys them an authorization failure after they
		// have filled the dialog in.
		mocks.isAdmin = false;
		render(<EntityTypeGraphView ownerSlug="acme" />);

		expect(
			screen.queryByRole("button", { name: "New relationship" }),
		).toBeNull();
		expect(
			screen.queryByRole("button", { name: "Create entity type" }),
		).toBeNull();
		// The dialog is gated on its own, not merely on its trigger being hidden.
		expect(screen.queryByTestId("new-relationship-dialog")).toBeNull();
		// Reading the map stays public — the member still sees the schema.
		expect(screen.getByTestId("react-flow")).toBeTruthy();
	});

	it("does not push a non-admin toward a create they cannot perform", () => {
		mocks.isAdmin = false;
		mocks.hasTypes = false;
