echo '<figure><figcaption><span class="title">After</span><span class="chip now">this PR</span></figcaption>'
echo -n '<img class="shot" alt="At 900px with the fix: a Clusters button in the toolbar opens a popover with the same index." src="data:image/png;base64,'
base64 -i cp-narrow.png | tr -d '\n'
echo '"><ul><li><span class="count good">Clusters 1</span><span>A toolbar button carrying the cluster count opens the same index in a popover &mdash; both the groups and the &ldquo;No relationships&rdquo; list.</span></li><li><span class="count good">public-read</span><span>The trigger sits outside the admin gate: reading the map is public, only the authoring buttons are admin-only.</span></li></ul></figure>'
echo '<figure><figcaption><span class="title">Unchanged above 1024px</span><span class="chip">1400&thinsp;px</span></figcaption>'
echo -n '<img class="shot" alt="At 1400px the sidebar renders as before and the button is hidden." src="data:image/png;base64,'
base64 -i cp-wide.png | tr -d '\n'
echo '"><ul><li><span class="count good">unchanged</span><span>Sidebar visible, button hidden. Measured: <code>sidebarVisible: true, triggerVisible: false</code>.</span></li></ul></figure>'
echo '<footer>Both presentations render one shared <code>SchemaClusterIndex</code>, so they cannot drift apart. Captured against the branch database via headed Playwright at 900&thinsp;px and 1400&thinsp;px.</footer>'
echo '</div>'
} > cluster-panel-comparison.html
ls -la cluster-panel-comparison.html

